#include <bits/stdc++.h>
using namespace std;
using ll = long long;
void solve(){
    int n1;
    cin >> n1;
    int sz = 3*n1;
    vector<ll>arr(sz);
    for( auto &val : arr){
        cin >> val;
    }
    sort(arr.rbegin(),arr.rend());
    vector<ll>psum(sz+1,0);
    for( int idx = 0;idx<sz;idx++){
        psum[idx+1] = psum[idx] + arr[idx];
    }
    ll res =0;
    for( int a1 = 0;a1<=n1;a1++){
        int lb = n1-a1;
        int lptr=0;
        int rptr = lb;
        
        while( lptr<rptr){
            int mid = lptr+ ( rptr-lptr)/2;
            int lt = a1+2*mid;
            int rt = sz-2*a1-mid-1;
            ll diff = arr[lt] + arr[lt+1]-3LL*arr[rt];
            if( diff >=0){
                lptr = mid+1;
            }
            else {
                rptr = mid;
            }
        }
        int opt[2] = { lptr, lptr-1};
        for( int b1 : opt){
            if( b1 <0 || b1 > lb){
                continue;
            }
        
        int c1 = n1-a1-b1;
        int posx = a1 + 2*b1;
        int posy = sz- 2*a1-b1;
        ll temp  = 2LL*psum[a1]+ psum[posx] + 3LL*psum[posy];
        if( temp > res){
            res = temp;
            }
        }
    }
     cout << res<< endl;
}


int main() {
     int tc;
     if( cin >>tc){
         while( tc--){
             solve();
         }
     }
     return 0;
}
